<style lang="scss" scoped src="./d-color-picker.scss"></style>

<script>
import { Chrome as ChromeColorPicker } from "vue-color";
import { Component, Vue } from "vue-property-decorator";
import Button from "../button/button";
import { ButtonSize } from "../button/button.constants";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Popover from "../popover/popover";

@Component({
  components: {
    Button,
    Icon,
    Popover,
    ChromeColorPicker,
  },
})
export default class DColorPicker extends Vue {
  color = "#FFFFFF";

  get IconShape() {
    return IconShape;
  }

  get ButtonSize() {
    return ButtonSize;
  }

  focusInput() {
    this.$refs.chromeColorPicker?.$el
      .querySelector(".vc-input__input")
      ?.focus();
  }

  handleInput(color) {
    this.color = color;

    // focus the input when a color is chosen/entered
    this.focusInput();
  }

  handleAddNewColor(close) {
    this.$emit("pick", this.color, close);
  }

  handleEnter(e) {
    if (e.key === "Enter") {
      this.handleAddNewColor();
      this.$refs.openColorPickerButton.click();
    }
  }

  handleShow() {
    setTimeout(() => {
      this.focusInput();
    }, 50);
  }

  mounted() {
    this.$refs.chromeColorPicker?.$el
      ?.querySelector(".vc-chrome-toggle-btn")
      ?.remove();

    // listener for "Enter" key press
    this.$refs.chromeColorPicker?.$el?.addEventListener(
      "keypress",
      this.handleEnter
    );
  }

  destroyed() {
    // clean up event listener
    this.$refs.chromeColorPicker?.$el?.removeEventListener("keypress");
  }
}
</script>

<template>
  <Popover class="DColorPicker" @show="handleShow">
    <template #trigger="{ open }">
      <button
        ref="openColorPickerButton"
        aria-label="Add New Color"
        class="DColorPicker__button"
        @click="open"
      >
        <Icon :shape="IconShape.T_PLUS" :color="'white'"></Icon>
      </button>
    </template>
    <template #popover="{ close }">
      <div>
        <ChromeColorPicker
          :value="color"
          @input="handleInput"
          ref="chromeColorPicker"
          disableAlpha
        />
        <div class="DColorPicker__add-color-button-container">
          <Button
            class="DColorPicker__add-color-button"
            :size="ButtonSize.SMALL"
            :icon="IconShape.T_PLUS"
            stretch
            @click="handleAddNewColor(close)"
          >
            Add New Color
          </Button>
        </div>
      </div>
    </template>
  </Popover>
</template>
